<template><div v-if="d" class="shade" @mousedown.self="dismiss"><section :key="d.id" ref="panel" class="modal" :class="d.className" role="dialog" aria-modal="true" :aria-labelledby="'dialog-'+d.id" @keydown="trap"><header class="modal-top"><h2 :id="'dialog-'+d.id">{{d.title}}</h2><button class="icon-button" type="button" aria-label="关闭" :disabled="d.busy" @click="dismiss"><Icon name="close"/></button></header><form @submit.prevent="submit"><div class="modal-body"><p v-if="d.description" class="form-note">{{d.description}}</p><template v-if="d.kind==='preferences'"><fieldset class="primary-colors"><legend>主色调</legend><div class="primary-options"><label class="theme-option" v-for="theme in [['blue','商务蓝','默认配色'],['green','浅绿','清新柔和']]" :key="theme[0]" :data-color="theme[0]"><input class="theme-radio" type="radio" name="primaryColor" :value="theme[0]" v-model="d.values.primaryColor" @change="applyPrefs(d.values)"/><span class="theme-card"><span class="theme-swatch"/><span class="theme-name"><strong>{{theme[1]}}</strong><small>{{theme[2]}}</small></span><span class="theme-check"><Icon name="check"/></span></span></label></div><p class="theme-preview-note">点击预览，保存后记住选择；取消将恢复原设置。</p></fieldset></template>
<label class="field" v-for="field in d.fields" :key="field.key"><span>{{field.label}}</span><select v-if="field.type==='select'" class="input" v-model="d.values[field.key]" :disabled="d.busy"><option v-for="o in field.options" :key="o[0]" :value="o[0]">{{o[1]}}</option></select><textarea v-else-if="field.type==='textarea'" class="input input-area" v-model="d.values[field.key]" :required="field.required" :maxlength="field.maxlength||20000"/><input v-else-if="field.type==='checkbox'" type="checkbox" class="switch" v-model="d.values[field.key]"/><TargetPicker v-else-if="['folder','file'].includes(field.type)" :files="field.type==='file'" v-model="d.values[field.key]" :fixed-scope="field.fixedScope" :exclude="field.exclude||[]"/><OrgPicker v-else-if="field.type==='org'" v-model="d.values[field.key]" :kind="d.values.targetType||'person'"/><input v-else class="input" :type="field.type||'text'" v-model="d.values[field.key]" :required="field.required" :min="field.min" :max="field.max" :maxlength="field.maxlength||255" :placeholder="field.placeholder||''" :disabled="d.busy"/></label>
<div v-if="d.kind==='upload'" class="upload-zone" @dragover.prevent @drop.prevent="addFiles($event.dataTransfer.files)"><Icon name="upload"/><strong>点击选择，或拖放文件到这里</strong><p>支持一次选择多个文件，上传进度在传输记录中查看</p><label class="btn primary small">选择文件<input type="file" multiple hidden @change="addFiles($event.target.files)"/></label></div>
<div v-if="d.kind==='transfers'" class="transfer-list"><div v-for="entry in ui.queue" :key="entry.id" class="transfer-item"><Icon name="upload"/><div class="truncate"><strong>{{entry.name}}</strong><p>{{size(entry.sizeBytes)}} · {{statuses[entry.status]}} <span v-if="entry.status==='uploading'">{{entry.progress}}%</span></p><p v-if="entry.error" class="error-text">{{entry.error}}</p><progress v-if="entry.status==='uploading'" :value="entry.progress" max="100"/></div><button v-if="entry.status==='failed'&&entry.file" class="text-button" type="button" @click="retry(entry)">重试</button><button v-if="entry.status==='waiting'" class="text-button" type="button" @click="entry.status='cancelled'">取消</button></div></div>
<div class="record-list" v-if="d.records?.length"><div class="member" v-for="r in d.records" :key="r.id"><span class="avatar">{{(r.name||'文').slice(0,1)}}</span><div class="member-info"><strong class="member-name">{{r.name}}</strong><p class="member-sub">{{r.description}}</p></div><button v-for="a in r.actions||[]" :key="a.label" class="text-button" :disabled="d.busy||a.disabled" type="button" @click="recordAction(a,r)">{{a.label}}</button></div></div><p v-if="d.kind==='transfers'&&!ui.queue.length&&!d.records.length" class="form-note">暂无传输记录</p>
<button v-if="d.kind==='preferences'" class="text-button prefs-reset" type="button" @click="resetPreferences">恢复界面默认设置</button><p v-if="d.error" class="error-text" role="alert">{{d.error}}</p></div><footer class="modal-foot"><button class="btn" type="button" :disabled="d.busy" @click="dismiss">{{d.onSubmit?'取消':'关闭'}}</button><button v-if="d.onSubmit" class="btn" :class="d.danger?'danger':'primary'" type="submit" :disabled="d.busy">{{d.busy?'处理中…':(d.submitLabel||'保存')}}</button></footer></form></section></div></template>
<script setup>
import { defaultPreferences } from '../preferences';
import {computed,ref,watch,nextTick} from 'vue';import {ui,closeDialog,applyPrefs,processQueue,enqueue} from '../state';import Icon from './Icon.vue';import OrgPicker from './OrgPicker.vue';import TargetPicker from './TargetPicker.vue';import {formatFileSize as size} from '../../utils/formatters';
const panel=ref(null),d=computed(()=>ui.dialogs.at(-1));const statuses={waiting:'等待上传',uploading:'上传中',done:'上传成功',failed:'上传失败',cancelled:'已取消'};
function dismiss(){if(!d.value?.busy)closeDialog();}
function trap(e){if(e.key==='Escape'){e.stopPropagation();dismiss();return;}if(e.key!=='Tab')return;const list=[...panel.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!list.length)return;if(e.shiftKey&&document.activeElement===list[0]){e.preventDefault();list.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===list.at(-1)){e.preventDefault();list[0].focus();}}
async function submit(){const current=d.value;if(current.busy)return;current.busy=true;current.error='';try{const result=await current.onSubmit(current.values,current);if(d.value?.id===current.id)closeDialog(result??true);}catch(e){current.error=e.message||'操作失败';}finally{current.busy=false;}}
async function recordAction(a,r){const current=d.value;try{await a.run(r);}catch(e){if(d.value?.id===current?.id)d.value.error=e.message;}}
function addFiles(files){if(!files?.length)return;enqueue(Array.from(files),d.value.target);closeDialog(true);}
function retry(entry){entry.status='waiting';entry.progress=0;void processQueue();}
function resetPreferences(){d.value.values=defaultPreferences();applyPrefs(d.value.values);}
watch(()=>d.value?.id,async()=>{await nextTick();panel.value?.querySelector('input:not([type="hidden"]),select,textarea,button')?.focus({preventScroll:true});});
</script>
